// Cal.com payload normalize karo (BOOKING_CREATED ya BOOKING_CANCELLED)
const body = $input.item.json.body || $input.item.json;
const triggerEvent = body.triggerEvent || body.type || '';
const payload = body.payload || body;
const attendee = (payload.attendees && payload.attendees[0]) || {};

return [{
  json: {
    trigger_event: triggerEvent,
    booking_uid: payload.uid || payload.uuid || '',
    attendee_email: (attendee.email || '').toLowerCase().trim(),
    attendee_name: attendee.name || '',
    start_time: payload.startTime || '',
    end_time: payload.endTime || '',
    meeting_url: payload.location || payload.videoCallUrl || '',
    title: payload.title || 'Discovery Call'
  }
}];

